import{_ as e,o as s,c as t,a3 as i}from"./chunks/framework.WFmvnizL.js";const k=JSON.parse('{"title":"Agent 开发","description":"哪吒 Agent 开发指南：本地构建、测试身份、指标与 protobuf 数据流、运行时配置快照、远程任务门禁和跨仓库兼容测试。","frontmatter":{"description":"哪吒 Agent 开发指南：本地构建、测试身份、指标与 protobuf 数据流、运行时配置快照、远程任务门禁和跨仓库兼容测试。","outline":"deep"},"headers":[],"relativePath":"developer/agent-development.md","filePath":"developer/agent-development.md","lastUpdated":1792850916000}'),n={name:"developer/agent-development.md"};function o(d,a,l,h,p,r){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="agent-开发" tabindex="-1">Agent 开发 <a class="header-anchor" href="#agent-开发" aria-label="Permalink to &quot;Agent 开发&quot;">​</a></h1><p>Agent 是独立 Go 程序，负责指标采集、探测与授权的远程操作。UI 修改一般不需要改 Agent；添加采集字段或远程能力才需要沿数据流协调多仓库。</p><h2 id="本地构建与测试实例" tabindex="-1">本地构建与测试实例 <a class="header-anchor" href="#本地构建与测试实例" aria-label="Permalink to &quot;本地构建与测试实例&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/nezhahq/agent.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/nezha-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/agent</span></span></code></pre></div><p>工具链以 <code>go.mod</code> 为准。发行构建的平台矩阵与 <code>-ldflags</code> 见 <code>.goreleaser.yml</code>；默认本地构建版本不是正式发布，不要为了调试替换系统 Agent。</p><p>新建独立的 <code>dev-config.yml</code>，填入本地测试 Dashboard 地址及测试用户连接密钥；不要复制生产 UUID。连接、TLS 和参数格式见<a href="/configuration/agent.html">Agent 配置</a>。在终端前台启动：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/nezha-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev-config.yml</span></span></code></pre></div><p>默认配置位置是二进制旁的 <code>config.yml</code>，不是当前 shell 目录。首次生成的 UUID 应保存，复制同一 UUID 同时运行两个实例会混淆身份。开发时通常不必安装系统服务，退出前台进程即可停止测试实例。</p><h2 id="源码数据流" tabindex="-1">源码数据流 <a class="header-anchor" href="#源码数据流" aria-label="Permalink to &quot;源码数据流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>关注点</th></tr></thead><tbody><tr><td><code>model/config.go</code></td><td>字段、克隆、加载、校验与保存</td></tr><tr><td><code>pkg/monitor</code></td><td>主机信息、状态、网卡、GPU 和 IP 发现</td></tr><tr><td><code>proto/nezha.proto</code></td><td>与 Dashboard 的 gRPC 消息契约</td></tr><tr><td><code>cmd/agent</code></td><td>连接、上报、运行时快照、任务与生命周期</td></tr><tr><td><code>pkg/fm</code> 等能力包</td><td>文件与传输等具体实现</td></tr></tbody></table><p>添加指标时，从采集函数经 <code>model</code> / <code>PB()</code> 转换检查到 protobuf，再检查 Dashboard 的接收、缓存、HTTP/WS 序列化和主题展示。仅在 Agent 端加字段不会自动出现历史图表；TSDB 写入、查询 API 和前端单位也要显式接入。</p><h2 id="修改运行时配置" tabindex="-1">修改运行时配置 <a class="header-anchor" href="#修改运行时配置" aria-label="Permalink to &quot;修改运行时配置&quot;">​</a></h2><p>配置用于多个并发工作线程。按现有设计读取不可变运行时快照，不直接并发修改共享配置或其 map/slice。新增字段需同时考虑：</p><ol><li><code>AgentConfig</code> 的 YAML/JSON 字段及默认/范围校验。</li><li><code>Clone()</code> 对新增集合进行深拷贝。</li><li>对应消费者的配置视图，保证一次操作使用同一代配置。</li><li>远程接受、延迟应用、先保存再发布、失败恢复与连接重建。</li><li>哪些值只在启动时读取，哪些可重载，并更新配置文档。</li></ol><p>不要不加检查地执行 <code>go generate ./...</code>：文件里存在生成指令不代表所引用的生成器在当前仓库中可用。以仓库实际生成工具和 CI 为准。</p><h2 id="添加任务时不能只测成功路径" tabindex="-1">添加任务时不能只测成功路径 <a class="header-anchor" href="#添加任务时不能只测成功路径" aria-label="Permalink to &quot;添加任务时不能只测成功路径&quot;">​</a></h2><p>命令、终端、文件、NAT 和服务探测有各自禁用门禁。新增执行路径必须复用已有开关；普通配置下发不能借机轮换 <code>client_secret</code>，服务器转移的密钥轮换使用专用任务，并要求新连接启用可验证 TLS。</p><p>为耗时操作传递 context、超时和取消；会话结束要回收 goroutine、流、文件和子进程。外部命令只应在明确的命令功能内执行，不要将文件名等普通参数拼进 shell。</p><p>验证至少覆盖断线、重连、取消、任务重复或乱序、配置切换中并发访问，以及进程退出后无残留资源。需要操作系统能力的测试使用临时目录和隔离进程，不能对开发者真实服务执行破坏性操作。</p><h2 id="protobuf-与跨仓库兼容" tabindex="-1">protobuf 与跨仓库兼容 <a class="header-anchor" href="#protobuf-与跨仓库兼容" aria-label="Permalink to &quot;protobuf 与跨仓库兼容&quot;">​</a></h2><p>保持已有字段编号，不复用已删除编号，新增能力保持缺省兼容。生成 Go 文件不是手写源码。修改协议时使用匹配工具重新生成 Dashboard 与 Agent 的产物，明确两个提交的配对关系。</p><p>Dashboard 的 <code>script/bootstrap.sh</code> 还会删除并复制相邻 <code>../agent/proto</code>；不要把它当作无副作用的 Swagger 命令。普通 API 文档只需<a href="/developer/api.html">单独运行 swag</a>。</p><p>本地基础检查：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -mod=readonly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -count=1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -mod=readonly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -race</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -shuffle=on</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -count=1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span></code></pre></div><p><code>-race</code> 需受支持的平台/编译器。跨仓库的 <code>agentcompat</code> 工作流验证固定配对的 Dashboard/Agent；涉及协议、连接或任务生命周期时按当前 CI 的固定 revision 与场景运行，不把普通单元测试视为等价替代。见<a href="/developer/testing.html">测试与贡献</a>。</p>`,25)])])}const g=e(n,[["render",o]]);export{k as __pageData,g as default};
